### `KtorPixabayApiService.kt` — implements the interface
```kotlin
package siarhei.luskanau.pixabayeye.core.network.ktor

import siarhei.luskanau.pixabayeye.core.network.api.*
import siarhei.luskanau.pixabayeye.core.network.ktor.model.HitResponse

internal class KtorPixabayApiService(private val client: PixabayApiClient) : PixabayApiService {

    override suspend fun isApiKeyOk(apiKey: String?): NetworkResult<Boolean> =
        runNetworkCatching { client.isApiKeyOk(apiKey = apiKey) }

    override suspend fun getImages(query: String?, perPage: Int?, page: Int?): NetworkResult<List<HitModel>> =
        runNetworkCatching {
            client.getImages(query = query, perPage = perPage, page = page).hits.map { it.toImageHitModel() }
        }

    override suspend fun getImage(imageId: Long): NetworkResult<HitModel> =
        runNetworkCatching { client.getImage(imageId = imageId).hits.first().toImageHitModel() }

    override suspend fun getVideos(query: String?, perPage: Int?, page: Int?): NetworkResult<List<HitModel>> =
        runNetworkCatching {
            client.getVideos(query = query, perPage = perPage, page = page).hits.map { it.toVideoHitModel() }
        }

    override suspend fun getVideo(videoId: Long): NetworkResult<HitModel> =
        runNetworkCatching { client.getVideo(videoId = videoId).hits.first().toVideoHitModel() }

    private suspend fun <T> runNetworkCatching(action: suspend () -> T): NetworkResult<T> =
        runCatching { action.invoke() }.fold(
            onSuccess = { NetworkResult.Success(it) },
            onFailure = { NetworkResult.Failure(it) }
        )
}

private fun HitResponse.toImageHitModel(): HitModel = HitModel(
    id = id, pageURL = pageURL, type = type, tags = tags,
    views = views, downloads = downloads, likes = likes, comments = comments,
    userId = userId, userName = userName, userImageURL = userImageURL,
    noAiTraining = noAiTraining, isAiGenerated = isAiGenerated,
    isGRated = isGRated, isLowQuality = isLowQuality, userURL = userURL,
    imageModel = ImageHitModel(
        previewUrl = requireNotNull(previewUrl), previewWidth = requireNotNull(previewWidth),
        previewHeight = requireNotNull(previewHeight), webFormatUrl = requireNotNull(webFormatUrl),
        webFormatWidth = requireNotNull(webFormatWidth), webFormatHeight = requireNotNull(webFormatHeight),
        largeImageUrl = requireNotNull(largeImageUrl), imageWidth = requireNotNull(imageWidth),
        imageHeight = requireNotNull(imageHeight), imageSize = requireNotNull(imageSize),
        collections = requireNotNull(collections)
    ),
    duration = null, videosModel = null
)

private fun HitResponse.toVideoHitModel(): HitModel = HitModel(
    id = id, pageURL = pageURL, type = type, tags = tags,
    views = views, downloads = downloads, likes = likes, comments = comments,
    userId = userId, userName = userName, userImageURL = userImageURL,
    noAiTraining = noAiTraining, isAiGenerated = isAiGenerated,
    isGRated = isGRated, isLowQuality = isLowQuality, userURL = userURL,
    imageModel = null,
    duration = duration,
    videosModel = videos.orEmpty().mapValues { (_, v) ->
        VideoHitModel(url = v.url, width = v.width, height = v.height, size = v.size, thumbnail = v.thumbnail)
    }
)
```

